pub fn section_subject(root: Rc<Node>, section: Rc<SectionRef>) -> Rc<Outcome<Rc<Node>>> {
    match (*section.clone()).clone() {
        SectionRef::DeclarationScope {
            declaration: declaration,
            ..
        } => subterm_at(root.clone(), declaration.path.clone()),
        SectionRef::NodeScope {
            declaration, node, ..
        } => bind_outcome(
            subterm_at(root.clone(), declaration.path.clone()),
            |declaration_subject| subterm_at(declaration_subject.clone(), node.path.clone()),
        ),
    }
}

