pub fn apply_lens<Output: Clone>(
    lens: Rc<Lens<Output>>,
    section: Rc<SectionRef>,
    root: Rc<Node>,
) -> Rc<Outcome<Output>> {
    bind_outcome(section_subject(root.clone(), section.clone()), |subject| {
        (lens.read)(subject.clone())
    })
}

pub fn apply_lens_enforce<Output: Clone, Budget: Clone, Projected: Clone>(
    enforceable: Rc<EnforceableLens<Output, Budget, Projected>>,
    section: Rc<SectionRef>,
    root: Rc<Node>,
    budget: Budget,
) -> Rc<Outcome<Rc<EnforcedLensResult<Output, Projected>>>> {
    bind_outcome(section_subject(root.clone(), section.clone()), |subject| {
        bind_outcome(
            (enforceable.lens.clone().read)(subject.clone()),
            |lens_output| {
                let enforcement_result =
                    lens_enforcement_result(enforceable.enforcement.clone(), lens_output.clone());
                if lens_enforcement_violated(
                    enforceable.enforcement.clone(),
                    lens_output.clone(),
                    budget.clone(),
                ) {
                    outcome_rejected(lens_enforcement_violation_diagnostic(
                        lens_enforcement_violation_input(
                            subject.clone(),
                            enforcement_result.projected.clone(),
                            budget.clone(),
                        ),
                    ))
                } else {
                    outcome_accepted(enforcement_result.clone())
                }
            },
        )
    })
}

